import json
with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)

# Search for anything related to Highway Trust Fund receipts and outlays for 1987-1991
def search_nested(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            search_nested(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_nested(item, f'{path}[{i}]')
    else:
        if 'highway' in str(d).lower() and ('receipt' in str(d).lower() or 'outlay' in str(d).lower() or '1987' in str(d) or '1988' in str(d) or '1989' in str(d) or '1990' in str(d) or '1991' in str(d)):
            print(f'{path}: {d}')

# Search in a simpler way
text = json.dumps(data).lower()
import re
# Find highway trust fund and years 1987-1991
matches = re.findall(r'highway.*?trust.*?fund.{0,200}(?:1987|1988|1989|1990|1991)', text)
for m in matches[:10]:
    print(m[:200])
"

